v_mov_b32 v12, s[sgprSizesFree+1]                  // set Free1 size
v_readfirstlane_b32 s[sgprNumWorkGroups0], v11     // set back to numWorkGroup0
v_cvt_f32_u32 v11, v13                             // v11 = ceil(v12 / v13)
s_delay_alu instid0(VALU_DEP_1)
v_rcp_iflag_f32 v11, v11                           // v11 = ceil(v12 / v13)
v_cvt_f32_u32 v14, v12                             // v11 = ceil(v12 / v13)
s_delay_alu instid0(VALU_DEP_1)
v_mul_f32 v11, v11, v14                            // v11 = ceil(v12 / v13)
s_delay_alu instid0(VALU_DEP_1)
v_cvt_u32_f32 v11, v11                             // v11 = ceil(v12 / v13)
v_mul_u32_u24 v14, v11, v13                        // v11 = ceil(v12 / v13)
v_sub_nc_u32 v14, v12, v14                         // v11 = ceil(v12 / v13)
s_delay_alu instid0(VALU_DEP_1)
v_cmp_ne_u32 vcc_lo, v14, 0                        // v11 = ceil(v12 / v13)
s_delay_alu instid0(VALU_DEP_4)
v_add_co_ci_u32 v11, vcc_lo, v11, 0, vcc_lo        // ceil
s_nop 0                                            // 1 wait states
v_readfirstlane_b32 s[sgprNumWorkGroups1], v11     // set back to numWorkGroup1
s_wait_kmcnt 0                                     // wait for -4/0 bytes of kern args

/* remap wg from 1D(idxWG012) to 3D(wg2,wg1,wg0) */
/* wg2 = idxWG012 * smallMagicNumber(1/(numWG0*numWG1)) */
s_mul_i32 s16, s[sgprNumWorkGroups0], s[sgprNumWorkGroups1]
s_and_b32 s17, s[sgprGSU], 0x3fff                  // Restore GSU
s_delay_alu instid0(SALU_CYCLE_1)
s_mul_i32 s16, s16, s17
v_cvt_f32_u32 v8, s16                              // s16 = s[sgprWorkGroup0] / s16
s_delay_alu instid0(VALU_DEP_1)
v_rcp_iflag_f32 v8, v8                             // s16 = s[sgprWorkGroup0] / s16
v_cvt_f32_u32 v9, s[sgprWorkGroup0]                // s16 = s[sgprWorkGroup0] / s16
s_delay_alu instid0(VALU_DEP_1)
v_mul_f32 v8, v8, v9                               // s16 = s[sgprWorkGroup0] / s16
s_delay_alu instid0(VALU_DEP_1)
v_cvt_u32_f32 v8, v8                               // s16 = s[sgprWorkGroup0] / s16
v_mul_u32_u24 v9, v8, s16                          // s16 = s[sgprWorkGroup0] / s16
v_sub_nc_u32 v9, s[sgprWorkGroup0], v9             // s16 = s[sgprWorkGroup0] / s16
v_cmp_eq_u32 vcc_lo, v9, s16                       // s16 = s[sgprWorkGroup0] / s16
s_mov_b32 exec_lo, vcc_lo                          // s16 = s[sgprWorkGroup0] / s16
s_delay_alu instid0(VALU_DEP_4)
v_add_nc_u32 v8, 1, v8                             // s16 = s[sgprWorkGroup0] / s16
s_mov_b32 exec_lo, -1                              // Reset exec
v_cmp_gt_u32 vcc_lo, v9, s16                       // overflow happened in remainder
s_mov_b32 exec_lo, vcc_lo                          // overflow happened in remainder
s_delay_alu instid0(VALU_DEP_2)
v_sub_nc_u32 v8, v8, 1                             // quotient - 1
s_mov_b32 exec_lo, -1                              // Reset exec
s_delay_alu instid0(VALU_DEP_1)
v_readfirstlane_b32 s16, v8                        // quotient
s_delay_alu instid0(SALU_CYCLE_1)
s_mov_b32 s[sgprWorkGroup2], s16
/* idxWG01 = idxWG012 - wg2 * numWG0 * numWG1 */
s_mul_i32 s16, s[sgprNumWorkGroups1], s[sgprNumWorkGroups0]
s_delay_alu instid0(SALU_CYCLE_1)
s_mul_i32 s16, s16, s[sgprWorkGroup2]
s_delay_alu instid0(SALU_CYCLE_1)
s_mul_i32 s16, s16, s17
s_sub_u32 s[sgprWorkGroup0], s[sgprWorkGroup0], s16
/* wg1 = idxWG01 * smallMagicNumber(1/numWG0) */
v_cvt_f32_u32 v8, s[sgprNumWorkGroups0]            // s16 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
s_delay_alu instid0(VALU_DEP_1)
v_rcp_iflag_f32 v8, v8                             // s16 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
v_cvt_f32_u32 v9, s[sgprWorkGroup0]                // s16 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
s_delay_alu instid0(VALU_DEP_1)
v_mul_f32 v8, v8, v9                               // s16 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
s_delay_alu instid0(VALU_DEP_1)
v_cvt_u32_f32 v8, v8                               // s16 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
v_mul_u32_u24 v9, v8, s[sgprNumWorkGroups0]        // s16 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
v_sub_nc_u32 v9, s[sgprWorkGroup0], v9             // s16 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
v_cmp_eq_u32 vcc_lo, v9, s[sgprNumWorkGroups0]     // s16 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
s_mov_b32 exec_lo, vcc_lo                          // s16 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
s_delay_alu instid0(VALU_DEP_4)
v_add_nc_u32 v8, 1, v8                             // s16 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
s_mov_b32 exec_lo, -1                              // Reset exec
v_cmp_gt_u32 vcc_lo, v9, s[sgprNumWorkGroups0]     // overflow happened in remainder
s_mov_b32 exec_lo, vcc_lo                          // overflow happened in remainder
s_delay_alu instid0(VALU_DEP_2)
v_sub_nc_u32 v8, v8, 1                             // quotient - 1
s_mov_b32 exec_lo, -1                              // Reset exec
s_delay_alu instid0(VALU_DEP_1)
v_readfirstlane_b32 s16, v8                        // quotient
s_mov_b32 s[sgprWorkGroup1], s16
/* wg0 = idxWG01 - wg1 * numWG0 */
s_mul_i32 s16, s[sgprWorkGroup1], s[sgprNumWorkGroups0]
s_delay_alu instid0(SALU_CYCLE_1)
s_sub_u32 s[sgprWorkGroup0], s[sgprWorkGroup0], s16
s_branch label_MultiGemmEnd
label_MultiGemm:

/* Check if custom structure pointer is null */
s_cmp_eq_u32 s[sgprArgType], 2                     // ArgType == 2 ?
s_cbranch_scc1 label_IsExternalValid               // branch if ArgType == 2
s_mov_b32 s15, 144                                 // KernArgAddressOffset
s_mul_i32 s22, s59, 4
s_mov_b64 s[16:17], s[sgprKernArgAddress:sgprKernArgAddress+1]
s_branch label_IsExternalValidEnd
label_IsExternalValid:
s_mov_b32 s15, 232
s_mov_b32 s22, 0
s_mov_b64 s[16:17], s[sgprKernArgAddress:sgprKernArgAddress+1]
label_IsExternalValidEnd:

/* Grouped Gemm:: prefetch 1 arg load */
s_mov_b32 s14, 1
s_mov_b32 s23, 0
s_load_b128 s[32:35], s[16:17], s22
s_mov_b32 s24, 1
s_cmp_eq_u32 s59, s24                              // if gemm_count is 1?
s_cbranch_scc1 label_wgTable_noLoadLoop

/* Grouped Gemm:: accumulate numTiles for each gemm */
/* Grouped Gemm:: loop start */
label_Loop_GemmCount:
s_wait_kmcnt 0
s_lshr_b32 s20, s32, 6                             // s20 = s32 / 64
s_and_b32 s18, 63, s32                             // s18 = s32 % 64
s_addc_u32 s20, s20, 0
s_lshr_b32 s21, s33, 6                             // s21 = s33 / 64
s_and_b32 s18, 63, s33                             // s18 = s33 % 64
s_addc_u32 s21, s21, 0
s_mul_i32 s20, s20, s21
s_mul_i32 s20, s20, s34
s_and_b32 s21, s[sgprGSU], 0x3fff                  // Restore GSU
s_delay_alu instid0(SALU_CYCLE_1)
s_mul_i32 s20, s20, s21
s_delay_alu instid0(SALU_CYCLE_1)
s_add_u32 s23, s23, s20
s_cmp_lt_u32 s[sgprWorkGroup0], s23
s_cbranch_scc1 label_FOUND
s_add_u32 s22, s22, s15
s_load_b128 s[32:35], s[16:17], s22
s_add_u32 s14, s14, 1
s_cmp_lt_u32 s14, s59
s_cbranch_scc1 label_Loop_GemmCount

/* Grouped Gemm:: noLoadLoop */
label_wgTable_noLoadLoop:
s_wait_kmcnt 0
s_lshr_b32 s20, s32, 6                             // s20 = s32 / 64
s_and_b32 s18, 63, s32                             // s18 = s32 % 64
s_addc_u32 s20, s20, 0
s_lshr_b32 s21, s33, 6                             // s21 = s33 / 64
s_and_b32 s18, 63, s33                             // s18 = s33 % 64
s_addc_u32 s21, s21, 0
s_mul_i32 s20, s20, s21
s_mul_i32 s20, s20, s34
s_and_b32 s16, s[sgprGSU], 0x3fff                  // Restore GSU
s_delay_alu instid0(SALU_CYCLE_1)
s_mul_i32 s20, s20, s16
s_delay_alu instid0(SALU_CYCLE_1)
s_add_u32 s23, s23, s20

/* Grouped Gemm:: gemmIndex found */
label_FOUND:
s_sub_u32 s17, s14, 1
s_sub_u32 s16, s23, s20
s_sub_u32 s[sgprWorkGroup0], s[sgprWorkGroup0], s16
/* Check if custom structure pointer is null */
s_cmp_eq_u32 s[sgprArgType], 2                     // ArgType == 2 ?
s_cbranch_scc1 label_LoadExternalStruct            // branch if ArgType == 2

/* Grouped Gemm: offset argument address to gemm */
/* Grouped Gemm: offset address from wg_table_start to args_start */
s_lshl2_add_u32 s[sgprKernArgAddress], s59, s[sgprKernArgAddress]
s_addc_u32 s[sgprKernArgAddress+1], s[sgprKernArgAddress+1], 0
/* Grouped Gemm: offset address from args_start to gemm_start */
s_mul_i32 s17, s17, 144                            // KernArgAddressOffset
s_delay_alu instid0(SALU_CYCLE_1)
s_add_u32 s[sgprKernArgAddress], s[sgprKernArgAddress], s17
s_addc_u32 s[sgprKernArgAddress+1], s[sgprKernArgAddress+1], 0

/* Load Kernel Args */
s_load_b512 s[36:51], s[sgprKernArgAddress:sgprKernArgAddress+1], 16 // 16
s_load_b128 s[52:55], s[sgprKernArgAddress:sgprKernArgAddress+1], 80 // 80
s_load_b64 s[56:57], s[sgprKernArgAddress:sgprKernArgAddress+1], 96 // 96
s_branch label_LoadExternalStructEnd
label_LoadExternalStruct:
/* Grouped Gemm: offset address from args_start to gemm_start */
s_mul_i32 s17, s17, 232
s_delay_alu instid0(SALU_CYCLE_1)
s_add_u32 s[sgprKernArgAddress], s[sgprKernArgAddress], s17
s_addc_u32 s[sgprKernArgAddress+1], s[sgprKernArgAddress+1], 0
s_load_b512 s[36:51], s[sgprKernArgAddress:sgprKernArgAddress+1], 16 // 16
s_load_b128 s[52:55], s[sgprKernArgAddress:sgprKernArgAddress+1], 80 // 80
s_load_b32 s56, s[sgprKernArgAddress:sgprKernArgAddress+1], 96 // 96
// Read Beta
s_load_b32 s57, s[sgprKernArgAddress:sgprKernArgAddress+1], 112 // 112
label_LoadExternalStructEnd:
/* init: add vgpr [44...242) to pool */
/* init: add vgpr [0...32) to pool */
/* init: add agpr [0...0) to pool */

/******************************************/
/* Local Read Addresses                   */
/******************************************/

/* local read addresses: tile assignments a/b */
/* lr0I */
s_nop 0
s_set_vgpr_msb 0                                   // src0: 0, src1: 0, src2: 0, dst: 0
v_and_b32 v1, 31, v[vgprSerial]                    // 0. thread id in wave: wtid = tid % wavelength(32)
v_and_b32 v0, 15, v1                               // 1. N offset: nIdx = wtid % MI_N(16)
                                                   // 1. N offset: nOffset = nIdx * nStride(1) (multiplier is 1, do nothing)
/* Skip. 2. block offset: bnOffset = 0 when num1DBlocks = 1 */
                                                   // 4. apply VectorWidth: bnOffset = bnOffset * vw(1) (multiplier is 1, do nothing)
v_lshrrev_b32 v1, 4, v1                            // 5. K offset: kIdx = wtid / (MIN(16) * MIBB(1))
v_lshl_add_u32 v0, v1, 11, v0                      // 5. K offset: lrKOffset = kIdx * mStride(2048); 6. offset in wave: lrOffset = bnOffset + lrKOffset
v_lshrrev_b32 v4, 5, v[vgprSerial]                 // 7. wave offset in N dimen: wtid = tid / dividedForWaveId(32)
v_and_b32 v4, 1, v4                                // 7. wave offset in M dimen: wtid0 = wtid / num1DWaves(2)
v_lshl_add_u32 v0, v4, 4, v0                       // 7. wave offset in M dimen: wOffset = wtid0 * W0Stride(16); 7. final local read offset: flrOffset = lrOffset + WOffset
/* lr1J */
v_and_b32 v2, 31, v[vgprSerial]                    // 0. thread id in wave: wtid = tid % wavelength(32)
v_and_b32 v1, 15, v2                               // 1. N offset: nIdx = wtid % MI_N(16)
v_lshlrev_b32 v1, 6, v1                            // 1. N offset: nOffset = nIdx * nStride(64)
/* Skip. 2. block offset: bnOffset = 0 when num1DBlocks = 1 */
                                                   // 4. apply VectorWidth: bnOffset = bnOffset * vw(1) (multiplier is 1, do nothing)
v_lshrrev_b32 v2, 4, v2                            // 5. K offset: kIdx = wtid / (MIN(16) * MIBB(1))
v_lshl_add_u32 v1, v2, 4, v1                       // 5. K offset: lrKOffset = kIdx * mStride(16); 6. offset in wave: lrOffset = bnOffset + lrKOffset
v_lshrrev_b32 v3, 6, v[vgprSerial]                 // 7. wave offset in N dimen: wtid = tid / dividedForWaveId(64)
v_and_b32 v3, 1, v3                                // 7. wave offset in M dimen: wtid0 = wtid / num1DWaves(2)
v_lshl_add_u32 v1, v3, 10, v1                      // 7. wave offset in M dimen: wOffset = wtid0 * W0Stride(1024); 7. final local read offset: flrOffset = lrOffset + WOffset
/* lr1J */
v_and_b32 v3, 31, v[vgprSerial]                    // 0. thread id in wave: wtid = tid % wavelength(32)
v_and_b32 v2, 15, v3                               // 1. N offset: nIdx = wtid % MI_N(16)
v_mul_lo_u32 v2, 20, v2                            // 1. N offset: nOffset = nIdx * nStride(20)
/* Skip. 2. block offset: bnOffset = 0 when num1DBlocks = 1 */
                                                   // 4. apply VectorWidth: bnOffset = bnOffset * vw(1) (multiplier is 1, do nothing)
v_lshrrev_b32 v3, 4, v3                            // 5. K offset: kIdx = wtid / (MIN(16) * MIBB(1))
v_lshl_add_u32 v2, v3, 3, v2                       // 5. K offset: lrKOffset = kIdx * mStride(8); 6. offset in wave: lrOffset = bnOffset + lrKOffset
v_lshrrev_b32 v6, 6, v[vgprSerial]                 // 7. wave offset in N dimen: wtid = tid / dividedForWaveId(64)
v_and_b32 v6, 1, v6                                // 7. wave offset in M dimen: wtid0 = wtid / num1DWaves(2)
s_mov_b32 s16, 320                                 // 7. wave offset in M dimen: wOffset = wtid0 * W0Stride(320); 7. final local read offset: flrOffset = lrOffset + WOffset
v_mad_u32_u24 v2, s16, v6, v2                      // 7. wave offset in M dimen: wOffset = wtid0 * W0Stride(320); 7. final local read offset: flrOffset = lrOffset + WOffset

/* local read addresses: final offsets a */
v_lshrrev_b32 v3, 5, v[vgprSerial]                 // 3 = Serial / 32
v_lshrrev_b32 v3, 2, v3                            // LSU offset: Get LSU wave_id
s_mov_b32 s16, 8192                                // LSU offset: stride = lsuStride(128)*(MT0(64) + PAD0(0))
v_mul_lo_u32 v3, s16, v3                           // LSU offset: lsuoffset = wave_id*lsuStride*(MT0+PAD)
v_add_nc_u32 v[vgprLocalReadAddrA], v3, v0         // Final Offset: offset = (lro0+lsuoffset)*bpeDS
                                                   //  (bpe is 1, do nothing)
v_lshrrev_b32 v4, 10, v[vgprLocalReadAddrA]        // Final Offset: padding 16 per block 1024
v_lshl_add_u32 v[vgprLocalReadAddrA], v4, 4, v[vgprLocalReadAddrA] // Final Offset: padding 16 per block 1024

/* local read addresses: final offsets metadata */
v_lshrrev_b32 v0, 5, v[vgprSerial]                 // 0 = Serial / 32
v_lshrrev_b32 v0, 2, v0                            // LSU offset: Get LSU wave_id
s_mov_b32 s16, 16                                  // LSU offset: stride = lsuStride(16) when umlds==True
v_mul_lo_u32 v0, s16, v0                           // LSU offset: lsuoffset = wave_id*lsuStride*(MT1+PAD)
v_add_nc_u32 v[vgprLocalReadAddrMetadata], v0, v2  // Final Offset: offset = (lro1+lsuoffset)*bpeDS
                                                   //  (bpe is 1, do nothing)

/* local read addresses: final offsets b */
v_lshrrev_b32 v0, 5, v[vgprSerial]                 // 0 = Serial / 32
v_lshrrev_b32 v0, 2, v0                            // LSU offset: Get LSU wave_id
s_mov_b32 s16, 64                                  // LSU offset: stride = lsuStride(64) when umlds==True
v_mul_lo_u32 v0, s16, v0                           // LSU offset: lsuoffset = wave_id*lsuStride*(MT1+PAD)
v_add_nc_u32 v[vgprLocalReadAddrB], v0, v1         // Final Offset: offset = (lro1+lsuoffset)*bpeDS
                                                   //  (bpe is 1, do nothing)
v_lshrrev_b32 v2, 8, v[vgprLocalReadAddrB]         // Final Offset: padding 16 per block 256
v_lshl_add_u32 v[vgprLocalReadAddrB], v2, 4, v[vgprLocalReadAddrB] // Final Offset: padding 16 per block 256

/* local read addresses: declare addresses a */

/* local read addresses: declare addresses metadata */
v_add_co_u32 v[vgprLocalReadAddrMetadata+0], vcc_lo, 0x2100, v[vgprLocalReadAddrMetadata+0] //  += LdsOffsetMetadata (lower)

/* local read addresses: declare addresses b */
v_add_co_u32 v[vgprLocalReadAddrB+0], vcc_lo, 0x2600, v[vgprLocalReadAddrB+0] //  += LdsOffsetB (lower)

/******************************************/
/* Local Write Addresses                  */
/******************************************/
/* LVCA = 4 */
/* v1 = A-unroll = serial/LVCA */
v_lshrrev_b32 v1, 2, v[vgprSerial]                 // 1 = Serial / 4
v_and_b32 v0, 3, v[vgprSerial]                     // 0 = Serial % 4
/* tile *= glvw */
v_lshlrev_b32 v0, 4, v0                            // v0 = v0 * 16
v_mov_b32 v4, v1                                   // copy for GlobalSplitU
/* LVCB = 4 */
/* v3 = B-unroll = serial%LVCB */
v_lshrrev_b32 v2, 2, v[vgprSerial]                 // 2 = Serial / 4
v_and_b32 v3, 3, v[vgprSerial]                     // 3 = Serial % 4
/* unroll *= glvw */
v_lshlrev_b32 v3, 4, v3                            // v3 = v3 * 16
v_mov_b32 v5, v3                                   // copy for GlobalSplitU
/* LVCMetadata = 2 */
/* v7 = Metadata-unroll = serial%LVCMetadata */
v_lshrrev_b32 v6, 1, v[vgprSerial]                 // 6 = Serial / 2
v_and_b32 v7, 1, v[vgprSerial]                     // 7 = Serial % 2
/* unroll *= glvw */
v_lshlrev_b32 v7, 3, v7                            // v7 = v7 * 8
v_mov_b32 v10, v7                                  // copy for GlobalSplitU
/* lwaUnrollAssignmentA = v4 */
/* lwaUnrollAssignmentB = v5 */
/* lwaUnrollAssignmentMetadata = v10 */

/* local write addresses: first offset a */
v_mul_u32_u24 v[vgprLocalWriteAddrA], 0x40, v4     // lwAL**(MTA + PAD)
v_add_nc_u32 v[vgprLocalWriteAddrA], v0, v[vgprLocalWriteAddrA] // lwFOA = (lwAA + lwAL*(MT0I+PAD))
                                                   //  (bpe is 1, do nothing)
v_lshrrev_b32 v8, 10, v[vgprLocalWriteAddrA]       // padding 16 per block 1024
v_lshl_add_u32 v[vgprLocalWriteAddrA], v8, 4, v[vgprLocalWriteAddrA] // padding 16 per block 1024

/* local write addresses: first offset metadata */
v_mul_u32_u24 v[vgprLocalWriteAddrMetadata], 0x14, v6 // lwMetadataL**(DepthU_Compute + PAD)
v_add_nc_u32 v[vgprLocalWriteAddrMetadata], v10, v[vgprLocalWriteAddrMetadata] // lwFOMetadata = (lwMetadataMetadata + lwMetadataL*(DepthU+PAD))
                                                   //  (bpe is 1, do nothing)
s_delay_alu instid0(VALU_DEP_1)
v_add_co_u32 v[vgprLocalWriteAddrMetadata], vcc_lo, 0x2100, v[vgprLocalWriteAddrMetadata] // lwFOMetadata = lw1J + lwL*MT1J + LDS_OFFSET_Metadata=8448

/* local write addresses: first offset b */
v_mul_u32_u24 v[vgprLocalWriteAddrB], 0x40, v2     // lwBL**(DepthU_Compute + PAD)
v_add_nc_u32 v[vgprLocalWriteAddrB], v5, v[vgprLocalWriteAddrB] // lwFOB = (lwBB + lwBL*(DepthU+PAD))
                                                   //  (bpe is 1, do nothing)
v_lshrrev_b32 v8, 8, v[vgprLocalWriteAddrB]        // padding 16 per block 256
v_lshl_add_u32 v[vgprLocalWriteAddrB], v8, 4, v[vgprLocalWriteAddrB] // padding 16 per block 256
s_delay_alu instid0(VALU_DEP_1)
v_add_co_u32 v[vgprLocalWriteAddrB], vcc_lo, 0x2600, v[vgprLocalWriteAddrB] // lwFOB = lw1J + lwL*MT1J + LDS_OFFSET_B=9728
v_mov_b32 v13, MT0                                 // set MT0 into sgpr
v_mov_b32 v12, s[sgprSizesFree+0]                  // set Free0 size
v_cvt_f32_u32 v11, v13                             // v11 = ceil(v12 / v13)
s_delay_alu instid0(VALU_DEP_1)
v_rcp_iflag_f32 v11, v11                           // v11 = ceil(v12 / v13)
v_cvt_f32_u32 v14, v12                             // v11 = ceil(v12 / v13)
s_delay_alu instid0(VALU_DEP_1)
v_mul_f32 v11, v11, v14                            // v11 = ceil(v12 / v13)
s_delay_alu instid0(VALU_DEP_1)
v_cvt_u32_f32 v11, v11                             // v11 = ceil(v12 / v13)
v_mul_u32_u24 v14, v11, v13                        // v11 = ceil(v12 / v13)
v_sub_nc_u32 v14, v12, v14                         // v11 = ceil(v12 / v13)
s_delay_alu instid0(VALU_DEP_1)
v_cmp_ne_u32 vcc_lo, v14, 0                        // v11 = ceil(v12 / v13)
s_delay_alu instid0(VALU_DEP_4)
v_add_co_ci_u32 v11, vcc_lo, v11, 0, vcc_lo        // ceil
v_mov_b32 v13, MT1                                 // set MT1 into sgpr
v_mov_b32 v12, s[sgprSizesFree+1]                  // set Free1 size
v_readfirstlane_b32 s[sgprNumWorkGroups0], v11     // set back to numWorkGroup0
v_cvt_f32_u32 v11, v13                             // v11 = ceil(v12 / v13)
s_delay_alu instid0(VALU_DEP_1)
v_rcp_iflag_f32 v11, v11                           // v11 = ceil(v12 / v13)
v_cvt_f32_u32 v14, v12                             // v11 = ceil(v12 / v13)
s_delay_alu instid0(VALU_DEP_1)
v_mul_f32 v11, v11, v14                            // v11 = ceil(v12 / v13)
s_delay_alu instid0(VALU_DEP_1)
v_cvt_u32_f32 v11, v11                             // v11 = ceil(v12 / v13)
v_mul_u32_u24 v14, v11, v13                        // v11 = ceil(v12 / v13)
v_sub_nc_u32 v14, v12, v14                         // v11 = ceil(v12 / v13)
s_delay_alu instid0(VALU_DEP_1)
v_cmp_ne_u32 vcc_lo, v14, 0                        // v11 = ceil(v12 / v13)
s_delay_alu instid0(VALU_DEP_4)
v_add_co_ci_u32 v11, vcc_lo, v11, 0, vcc_lo        // ceil
s_nop 0                                            // 1 wait states
v_readfirstlane_b32 s[sgprNumWorkGroups1], v11     // set back to numWorkGroup1
s_wait_kmcnt 0                                     // wait for -4/0 bytes of kern args

/* Early stop if N(SizeFreeJ) == 0 */
s_cmp_eq_u32 s[sgprSizeJ], 0
s_cbranch_scc0 label_NoEarlyStop_N0
label_EarlyStop_if_N_is_0:
s_endpgm
label_NoEarlyStop_N0:

/* remap wg from 1D(idxWG012) to 3D(wg2,wg1,wg0) */
/* wg2 = idxWG012 * smallMagicNumber(1/(numWG0*numWG1)) */
s_mul_i32 s16, s[sgprNumWorkGroups0], s[sgprNumWorkGroups1]
s_and_b32 s17, s[sgprGSU], 0x3fff                  // Restore GSU
s_delay_alu instid0(SALU_CYCLE_1)
s_mul_i32 s16, s16, s17
s_set_vgpr_msb 0                                   // src0: 0, src1: 0, src2: 0, dst: 0
v_cvt_f32_u32 v8, s16                              // s16 = s[sgprWorkGroup0] / s16
s_delay_alu instid0(VALU_DEP_1)
v_rcp_iflag_f32 v8, v8                             // s16 = s[sgprWorkGroup0] / s16
v_cvt_f32_u32 v9, s[sgprWorkGroup0]                // s16 = s[sgprWorkGroup0] / s16
s_delay_alu instid0(VALU_DEP_1)
v_mul_f32 v8, v8, v9                               // s16 = s[sgprWorkGroup0] / s16
s_delay_alu instid0(VALU_DEP_1)
v_cvt_u32_f32 v8, v8                               // s16 = s[sgprWorkGroup0] / s16
v_mul_u32_u24 v9, v8, s16                          // s16 = s[sgprWorkGroup0] / s16
v_sub_nc_u32 v9, s[sgprWorkGroup0], v9             // s16 = s[sgprWorkGroup0] / s16
v_cmp_eq_u32 vcc_lo, v9, s16                       // s16 = s[sgprWorkGroup0] / s16
s_mov_b32 exec_lo, vcc_lo                          // s16 = s[sgprWorkGroup0] / s16
s_delay_alu instid0(VALU_DEP_4)
v_add_nc_u32 v8, 1, v8                             // s16 = s[sgprWorkGroup0] / s16
s_mov_b32 exec_lo, -1                              // Reset exec
v_cmp_gt_u32 vcc_lo, v9, s16                       // overflow happened in remainder
s_mov_b32 exec_lo, vcc_lo                          // overflow happened in remainder
s_delay_alu instid0(VALU_DEP_2)
v_sub_nc_u32 v8, v8, 1                             // quotient - 1
s_mov_b32 exec_lo, -1                              // Reset exec
s_delay_alu instid0(VALU_DEP_1)
v_readfirstlane_b32 s16, v8                        // quotient
s_delay_alu instid0(SALU_CYCLE_1)
s_mov_b32 s[sgprWorkGroup2], s16
/* idxWG01 = idxWG012 - wg2 * numWG0 * numWG1 */
s_mul_i32 s16, s[sgprNumWorkGroups1], s[sgprNumWorkGroups0]
s_delay_alu instid0(SALU_CYCLE_1)
s_mul_i32 s16, s16, s[sgprWorkGroup2]
s_delay_alu instid0(SALU_CYCLE_1)
s_mul_i32 s16, s16, s17
s_sub_u32 s[sgprWorkGroup0], s[sgprWorkGroup0], s16
/* wg1 = idxWG01 * smallMagicNumber(1/numWG0) */
v_cvt_f32_u32 v8, s[sgprNumWorkGroups0]            // s16 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
s_delay_alu instid0(VALU_DEP_1)
v_rcp_iflag_f32 v8, v8                             // s16 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
v_cvt_f32_u32 v9, s[sgprWorkGroup0]                // s16 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
s_delay_alu instid0(VALU_DEP_1)
v_mul_f32 v8, v8, v9                               // s16 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
s_delay_alu instid0(VALU_DEP_1)
v_cvt_u32_f32 v8, v8                               // s16 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
v_mul_u32_u24 v9, v8, s[sgprNumWorkGroups0]        // s16 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
v_sub_nc_u32 v9, s[sgprWorkGroup0], v9             // s16 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
v_cmp_eq_u32 vcc_lo, v9, s[sgprNumWorkGroups0]     // s16 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
s_mov_b32 exec_lo, vcc_lo                          // s16 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
s_delay_alu instid0(VALU_DEP_4)
v_add_nc_u32 v8, 1, v8                             // s16 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
s_mov_b32 exec_lo, -1                              // Reset exec
v_cmp_gt_u32 vcc_lo, v9, s[sgprNumWorkGroups0]     // overflow happened in remainder
s_mov_b32 exec_lo, vcc_lo                          // overflow happened in remainder
s_delay_alu instid0(VALU_DEP_2)
v_sub_nc_u32 v8, v8, 1                             // quotient - 1
s_mov_b32 exec_lo, -1                              // Reset exec
s_delay_alu instid0(VALU_DEP_1)
v_readfirstlane_b32 s16, v8                        // quotient
s_mov_b32 s[sgprWorkGroup1], s16
/* wg0 = idxWG01 - wg1 * numWG0 */
s_mul_i32 s16, s[sgprWorkGroup1], s[sgprNumWorkGroups0]
s_delay_alu instid0(SALU_CYCLE_1)
s_sub_u32 s[sgprWorkGroup0], s[sgprWorkGroup0], s16

/* Early stop if wg exceed */
s_cmp_ge_u32 s[sgprWorkGroup2], s[sgprSizesFree+2]
s_cbranch_scc0 label_NoEarlyStop_wgExceed
label_EarlyStop_if_wg_exceed:
s_endpgm
label_NoEarlyStop_wgExceed:

label_MultiGemmEnd:
.set sgprSrdA, 24
.set sgprSrdB, 28
.set sgprSrdMetadata, 60
.set sgprShadowLimitA, 64
.set sgprShadowLimitB, 66
.set sgprShadowLimitMetadata, 68
.set sgprStaggerUIter, 59
.set sgprWrapUA, 70
.set sgprWrapUB, 72
.set sgprWrapUMetadata, 74
