s_delay_alu instid0(VALU_DEP_4)
v_add_nc_u32 v8, 1, v8                             // s[sgprGSUSumIdx] = s[sgprWorkGroup1] / s[sgprNumWorkGroups1]
v_mov_b32 v9, 0                                    // s[sgprWorkGroup1] = s[sgprWorkGroup1] % s[sgprNumWorkGroups1]
s_mov_b32 exec_lo, -1                              // Reset exec
v_cmp_gt_u32 vcc_lo, v9, s[sgprNumWorkGroups1]     // overflow happened in remainder
s_mov_b32 exec_lo, vcc_lo                          // overflow happened in remainder
s_delay_alu instid0(VALU_DEP_3)
v_sub_nc_u32 v8, v8, 1                             // quotient - 1
v_mul_u32_u24 v9, v8, s[sgprNumWorkGroups1]        // re-calculate remainder
v_sub_nc_u32 v9, s[sgprWorkGroup1], v9             // re-calculate remainder
s_mov_b32 exec_lo, -1                              // Reset exec
s_delay_alu instid0(VALU_DEP_3)
v_readfirstlane_b32 s[sgprGSUSumIdx], v8           // quotient
s_delay_alu instid0(VALU_DEP_2)
v_readfirstlane_b32 s[sgprWorkGroup1], v9          // remainder
