/* WGM Calculation */
s_mov_b32 s16, s[sgprWGM]                          // Restore WGM
s_delay_alu instid0(SALU_CYCLE_1)
s_sext_i32_i16 s16, s16                            // Restore WGM
s_delay_alu instid0(SALU_CYCLE_1)
