/* Multiply MI out register with Alpha -> C Vgpr register */
/* computeStoreVgprs */
s_nop 0
s_set_vgpr_msb 0                                   // src0: 0, src1: 0, src2: 0, dst: 0
v_lshrrev_b32 v36, 5, v[vgprSerial]                // 36 = Serial / 32
v_lshrrev_b32 v37, 1, v36                          // 37 = 36 / 2
